			Object.Destroy(gameObject, 0.25f);
		}
	}
}
##### AirSentry.cs
public class AirSentry : Projectile
{
	private static GameObject prefab;
	private static Vector3 thinScale = new Vector3(0.75f, 1f, 1f);
	public Transform sentryContainer;
	public GameObject sentryTemplate;
	private GameObject[] sentryObjArr;
	private Vector3 sentryPos;
	private int sentryCount = 10;
	private string skillCat = string.Empty;
	private string skillID = string.Empty;
	private List<GameObject> targetList;
	private List<GameObject> ignoreList;
	private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.1f);
	private TargetInfo currentInfo;
	private Arrow currentArrow;
	private Vector2 atkVector;
	private ParticleEffect shootEffect;
	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.08f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/AirSentry.prefab"));
	public void Init(List<GameObject> givenList, string givenCat, string givenID, int givenCount)
	{
		ignoreList = givenList;
		skillCat = givenCat;
		skillID = givenID;
		sentryCount = givenCount;
	}
	public override void Start()
	{
		base.Start();
		Vector2 vector = transform.position;
		sentryObjArr = new GameObject[sentryCount];
		sentryObjArr[0] = sentryTemplate;
		for (int i = 1; i < sentryCount; i++)
		{
			atkVector = Globals.GetCirclePositionVector(sentryCount, i);
			sentryObjArr[i] = Object.Instantiate(sentryTemplate, vector + atkVector * 0.75f, Globals.GetRotationQuaternion(atkVector), sentryContainer);
		}
		sentryObjArr.Shuffle();
	}
	public override void Update()
	{
		base.Update();
		PlayAudio();
		if (targetStopwatch.IsRunning)
		{
			return;
		}
		targetStopwatch.IsRunning = true;
		targetList = Entity.GetAllTargetsInRange(GameController.enemies, transform.position, 8f, playerTagOnly: false, ignoreList, parentObject, requireLOS: true, ChaosCollisio
		if (targetList.Count == 0)
		{
			return;
		}
		shootEffect = PoolManager.GetPoolItem<ParticleEffect>("SpinningCircleBurst");
		int num = Random.Range(1, 3);
		while (num >= 0 && targetList.Count != 0)
		{
			currentInfo = Entity.GetTargetInfoFromObject(targetList[0]);
			targetList.RemoveAt(0);
			if (currentInfo != null)
			{
				sentryCount--;
				if (sentryObjArr[sentryCount] != null)
				{
					sentryPos = sentryObjArr[sentryCount].transform.position;
					sentryObjArr[sentryCount].SetActive(value: false);
				}
				else
				{
					sentryPos = transform.position;
				}
				CreateArrow(sentryPos, (currentInfo.hurtBoxPosition - sentryPos).normalized);
				if (sentryCount <= 0)
				{
					ResetProjectile();
					break;
				}
			}
			num--;
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (sentryContainer != null)
		{
			sentryContainer.Rotate(rotationVector * Time.fixedDeltaTime);
		}
	}
	public override void ResetProjectile()
	{
		base.ResetProjectile();
		sentryPos = transform.position;
		WindBurst.CreateBurst(sentryPos, string.Empty, string.Empty, 1, 1.5f);
		PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect").Emit(1, sentryPos);
		for (int i = 0; i < sentryCount; i++)
		{
			CreateArrow(sentryPos, Random.insideUnitCircle.normalized);
		}
	}
	private void CreateArrow(Vector2 givenPosition, Vector2 givenVector)
	{
		currentArrow = (Arrow)Projectile.CreateProjectile(parentEntity, Arrow.Prefab, givenPosition, Globals.GetRotationQuaternion(givenVector));
		currentArrow.attackBox.SetAttackInfo(skillCat, skillID);
		currentArrow.attackBox.knockbackOverwriteVector = givenVector;
		currentArrow.moveVector = givenVector;
		currentArrow.moveSpeed = 32f;
		currentArrow.flyTime = 0.25f;
		currentArrow.disableOnHit = false;
		currentArrow.transform.localScale = thinScale;
		SoundManager.PlayWithDistAndSPR("WindSnap", givenPosition, 1.25f);
		if (shootEffect != null)
		{
			shootEffect.Emit(1, givenPosition, localEulerAngles: Globals.GetRotationVector(givenVector), overrides: ParticleEffectOverrides.StartLifeTime0p2);
		}
	}
	private void PlayAudio()
	{
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			SoundManager.PlayAudioWithDistance("WindCircle", transform.position, null, 24f, -1f, 1.25f);
		}
	}
}
##### AirSpinner.cs
public class AirSpinner : Projectile
{
	private static GameObject prefab;
	private Movement movement;
	private ParticleSystem windEmitter;
	private ParticleSystem blastEmitter;
	public Transform parentTrans;
	[HideInInspector]
	public float orbitRange = 2f;
	[HideInInspector]
	public bool isFinal;
	[HideInInspector]
	public Vector2 initVector;
	private bool resetCalled;
	private static AudioSource spinAudio;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/AirSpinner.prefab"));
	public override void Awake()
	{
		base.Awake();
		movement = GetComponent<Movement>();
		windEmitter = transform.Find("WindEmitter").GetComponent<ParticleSystem>();
		blastEmitter = transform.Find("BlastEmitter").GetComponent<ParticleSystem>();
	}
	public override void Start()
	{
		if (isFinal)
		{
			projectileSpriteRenderer.enabled = false;
			flyTime *= 0.4f;
			attackBox.GetComponent<CircleCollider2D>().radius = 2.75f;
			attackBox.EnableForOneFrame();
			ignoreProjectileCollisions = true;
			ignoreNegate = true;
			PoolManager.GetPoolItem<ParticleEffect>("AirSpinnerBurst").Emit(2, transform.position);
			SoundManager.PlayAudioWithDistance("StandardHeavySwing", transform.position, null, 24f, -1f, 1.4f);
		}
		else
		{
			windEmitter.Play();
			movement.orbitRadius = orbitRange;
			movement.InitOrbitAngle(initVector);
		}
		base.Start();
		if (Projectile.projectileShootEvent != null)
		{
			Projectile.projectileShootEvent(this);
		}
	}
	public override void FixedUpdate()
	{
		if (!isFinal)
		{
			if (movement != null && parentTrans != null)
			{
				movement.OrbitTarget(parentTrans.position);
			}
			spinAudio = SoundManager.PlayIfNotPlaying("StandardSpin", spinAudio, transform);
		}
	}
	public override void ResetProjectile()
	{
		if (!resetCalled)
		{
			resetCalled = true;
			parentTrans = null;
			movement.EndMovement();
			attackBox.gameObject.SetActive(value: false);
			windEmitter.Stop();
			if (!isFinal)
			{
				PoolManager.GetPoolItem<ParticleEffect>("WindTwirlSmallEffect").Emit(1, transform.position, localEulerAngles: new Vector3(0f, 0f, Random.Range(-30f, 30f)), overrides:
				DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
				int particleCount = 10;
				float scale = 0.1f;
				Vector3? emitPosition = transform.position;
				poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
			}
			if (gameObject != null)
			{
				Object.Destroy(gameObject);
			}
		}
	}
}
##### AirWave.cs
public class AirWave : Wave
{
	private new static GameObject prefab;
	private static ParticleSystemOverride _secondEmitOverride;
	public int durationStopwatchID;
	private Vector2 startPosition;
	private Vector2 endPosition;
	private AirWave respawnWave;
	private bool respawnQueued;
	public bool useChimes = true;
	private WaitForSeconds waitForDelay = new WaitForSeconds(0.02f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AirWave.prefab"));
	public static ParticleSystemOverride SecondEmitOverride
	{
		get
		{
			if (_secondEmitOverride == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.startColor = new Color(1f, 1f, 1f, 0.1f);
				particleSystemOverride.startLifetime = 0.175f;
				_secondEmitOverride = particleSystemOverride;
			}
			return _secondEmitOverride;
		}
	}
	public override void Awake()
	{
		base.Awake();
		stopLayerMask = ChaosCollisions.layerUpperWallAndObst;
	}
	public override void Start()
	{
		base.Start();
		startPosition = transform.position;
		endPosition = Globals.GetLinecastVector(startPosition, startPosition + moveVector * spacing * maxWaveCount, stopLayerMask) - moveVector * 0.5f;
	}
	public override void ActivateWave()
	{
		base.ActivateWave();
		wavePoolAnims[waveCount].speed = 1.25f;
		wavePoolTrans[waveCount].rotation = Globals.GetRotationQuaternion(moveVector);
		StartCoroutine(EmitShockwave(waveCount, moveVector));
		if (useChimes)
		{
			string audioID = "Chime";
			Vector2? soundOrigin = activationPosition;
			float overridePitch = Random.Range(0.75f, 1.5f);
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.125f, overridePitch);
		}
	}
	public override void StopWave(bool stop = true)
	{
		if (!respawnQueued)
		{
			respawnQueued = true;
			if (!ChaosStopwatch.Check(durationStopwatchID))
			{
				Respawn();
			}
			base.StopWave(stop);
		}
	}
	private void Respawn()
	{
		respawnWave = Globals.ChaosInst<AirWave>(Prefab, transform.parent, endPosition);
		respawnWave.SetSkillData(waveSkillCategory, waveSkillID);
		respawnWave.moveVector = -moveVector;
		respawnWave.spawnRate = spawnRate;
		respawnWave.maxWaveCount = maxWaveCount;
		respawnWave.wavePoolSize = wavePoolSize;
		respawnWave.durationStopwatchID = durationStopwatchID;
	}
	private IEnumerator EmitShockwave(int waveNo, Vector3 moveVec)
	{
		yield return waitForDelay;
		if (gameObject.activeSelf && !(wavePoolTrans[waveNo] == null) && wavePoolTrans[waveNo].gameObject.activeSelf)
		{
			PoolManager.GetPoolItem<ParticleEffect>("AirWaveShockwave").Emit(1, wavePoolTrans[waveNo].position - moveVec * 0.75f, localEulerAngles: Globals.GetRotationVector(moveV
			if (useChimes)
			{
				PoolManager.GetPoolItem<ParticleEffect>("MusicNoteBurstEmitter").Emit(1, wavePoolTrans[waveNo].position - moveVec * 0.75f);
			}
		}
	}
}
##### AquaCrest.cs
public class AquaCrest : Projectile
{
	private static GameObject prefab;
	private ChaosQuickStopwatch dropTimer;
	private float dropTime = 0.15f;
	private WaterDropEmitter currentWD;
	private Vector2 currentPosition;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/PlayerSkills/AquaCrest.prefab"));
	public override void Awake()
	{
		base.Awake();
		dropTimer = new ChaosQuickStopwatch(dropTime);
		dropTimer.IsRunning = true;
	}
	public override void Start()
	{
		base.Start();
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(1, transform.position);
	}
	public override void ResetProjectile()
	{
		WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
		int? particleCount = 1;
		Vector3? position = transform.position;
		Vector3? localEulerAngles = Globals.GetRotationVector(-moveVector);
		poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
		currentPosition = transform.position;
		currentWD = PoolManager.GetPoolItem<WaterDropEmitter>();
		currentWD.Emit(1, currentPosition + moveVector * Random.Range(-0.25f, 0.25f));
		currentWD.Emit(1, currentPosition + Globals.GetPerpendicular(moveVector));
		currentWD.Emit(1, currentPosition - Globals.GetPerpendicular(moveVector));
		base.ResetProjectile();
	}
	public override void Update()
	{
		base.Update();
		if (!dropTimer.IsRunning)
		{
			dropTimer.IsRunning = true;
