public class AquaPrisonProjectile : Projectile
{
	private static GameObject prefab;
	private bool targetHit;
	private Entity targetEntity;
	private AttackInfo initAtkInfo;
	private AttackInfo baseAtkInfo;
	private AttackInfo finalAtkInfo;
	private int hitCount = 6;
	private float hitDelay = 1f;
	private int prisonStopwatchID;
	private bool prisonDone;
	private bool releaseAnimPlayed;
	private static BoolVarStatMod ignoreKnockbackMod;
	private int waterDropEffectTimer = -1;
	private float waterDropInterval = 0.2f;
	private Vector2 currentPosition;
	public override void Awake()
	{
		base.Awake();
		targetEntity = null;
		targetHit = false;
		prisonDone = false;
		releaseAnimPlayed = false;
		if (ignoreKnockbackMod == null)
		{
			ignoreKnockbackMod = new BoolVarStatMod("AquaPrisonSkill", Health.skillIgnoreMod);
		}
	}
	public override void Start()
	{
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackBox.ChangeAttackInfoLevel(3);
		finalAtkInfo = new AttackInfo(attackBox.atkInfo);
		attackBox.ChangeAttackInfoLevel(2);
		baseAtkInfo = new AttackInfo(attackBox.atkInfo);
		attackBox.ChangeAttackInfoLevel(1);
		waterDropEffectTimer = ChaosStopwatch.Begin(waterDropInterval);
		currentPosition = transform.position;
		SoundManager.PlayAudioWithDistance("WaterArcBasic", currentPosition, null, 24f, -1f, 0.8f);
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(5, currentPosition + moveVector * 0.25f, WaterDropEmitter.MedWaterExplosionOverride);
		WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
		int? particleCount = 1;
		Vector3? position = currentPosition + moveVector * 0.66f;
		Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
		poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
	}
	public override void Update()
	{
		if (targetHit)
		{
			if (!prisonDone && targetEntity != null && targetEntity.gameObject != null && targetEntity.health.CurrentHealthValue > 0)
			{
				rigidbody2D.MovePosition(targetEntity.hurtBoxTransform.position);
				targetEntity.health.ignoreKnockbackVarStat.AddMod(ignoreKnockbackMod);
				switch (ChaosStopwatch.CheckInterval(prisonStopwatchID))
				{
				case StopwatchState.Ready:
					targetEntity.ignorePrevHitStunDuration = true;
					targetEntity.health.ignoreKnockbackVarStat.RemoveMod(ignoreKnockbackMod);
					if (ChaosStopwatch.GetRemainingIntervals(prisonStopwatchID) == 0)
					{
						targetEntity.health.TakeDamage(finalAtkInfo);
					}
					else
					{
						targetEntity.health.TakeDamage(baseAtkInfo);
						string audioID = "AquaPrisonLoop";
						Transform originTrans = transform;
						SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
					}
					anim.Play("Attack", -1, 0f);
					targetEntity.health.ignoreKnockbackVarStat.AddMod(ignoreKnockbackMod);
					break;
				case StopwatchState.Done:
					prisonDone = true;
					targetEntity.health.ignoreKnockbackVarStat.RemoveMod(ignoreKnockbackMod);
					break;
				}
			}
			else if (!releaseAnimPlayed)
			{
				releaseAnimPlayed = true;
				anim.Play("Release", -1, 0f);
				WaterDropEmitter.EmitCircle(transform.position, 2, 18, 1.5f);
			}
			else if (anim.AnimPlayed())
			{
				UnityEngine.Object.Destroy(gameObject);
			}
		}
		else
		{
			if (ChaosStopwatch.Check(waterDropEffectTimer))
			{
				waterDropEffectTimer = ChaosStopwatch.Begin(waterDropInterval);
				PoolManager.GetPoolItem<WaterDropEmitter>().Emit(2, transform.position - (Vector3)moveVector * 0.25f);
			}
			base.Update();
		}
	}
	public override void HandleCollision(Collider2D other)
	{
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(5, transform.position - (Vector3)moveVector);
		base.HandleCollision(other);
	}
	public override void ResetProjectile()
	{
		if (!targetHit)
		{
			PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, transform.position);
		}
		string audioID = "WaterExplode";
		Vector2? soundOrigin = transform.position;
		float standardPitchRange = SoundManager.StandardPitchRange;
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
		base.ResetProjectile();
	}
	private void OnTargetHit(Entity hitEntity)
	{
		if (!targetHit && !(hitEntity is Destructible) && !(hitEntity == null))
		{
			targetHit = true;
			targetEntity = hitEntity;
			rigidbody2D.velocity = Vector2.zero;
			attackBox.gameObject.SetActive(value: false);
			wallCollider.gameObject.SetActive(value: false);
			if (hitEntity is Player)
			{
				hitDelay *= 0.5f;
				hitCount -= 2;
			}
			prisonStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, hitCount - 1);
			if (targetEntity.health.IgnoreHurtState)
			{
				baseAtkInfo.slowChance = 1f;
			}
			updateVelocity = false;
			anim.Play("Grab", -1, 0f);
			WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
			int? particleCount = 1;
			Vector3? position = transform.position + (Vector3)moveVector.normalized * 0.5f;
			Vector3? localEulerAngles = Globals.GetRotationVector(-moveVector);
			poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
			string audioID = "AquaPrisonImpact";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}
	public void SetRotationZero()
	{
		transform.localEulerAngles = Vector3.zero;
	}
}
