##### Arrow
public class Arrow : Projectile
{
	private bool waitingForReset;
	private bool hitWall;
	private bool collided;
	private static GameObject prefab;
	private float elapsedTime;
	private Transform lightTrans;
	private Vector3 lightPos;
	private Light light;
	private bool fullLight;
	private bool startSpeedDecrement;
	private float speedDecrement;
	public bool useHoming;
	public override void Awake()
	{
		base.Awake();
		lightTrans = transform.Find("Light").transform;
		light = lightTrans.GetComponent<Light>();
		fullLight = false;
		startSpeedDecrement = false;
		speedDecrement = 100f;
	}
	public override void Start()
	{
		base.Start();
		if (useHoming)
		{
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = attackBox;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		elapsedTime = Time.fixedDeltaTime;
		if (!fullLight)
		{
			if (light.range < 4f)
			{
				light.range += elapsedTime * 40f;
			}
			else
			{
				fullLight = true;
			}
			return;
		}
		lightPos = lightTrans.position + (Vector3)moveVector * elapsedTime * 8f;
		lightPos.z = lightTrans.position.z - elapsedTime * 5f;
		lightTrans.position = lightPos;
		if (lightTrans.position.z > -1f)
		{
			startSpeedDecrement = true;
		}
		if (startSpeedDecrement && !waitingForReset)
		{
			speedDecrement += elapsedTime * 50f;
			moveSpeed = Mathf.Max(moveSpeed - elapsedTime * speedDecrement, 0f);
		}
		light.intensity -= elapsedTime * 5f;
		light.range -= elapsedTime * 5f;
	}
	public override void HandleCollision(Collider2D other)
	{
		collided = true;
		base.HandleCollision(other);
	}
	public override void HandleWallCollision(Collider2D other)
	{
		hitWall = true;
		collided = true;
		base.HandleWallCollision(other);
	}
	public override void ResetProjectile()
	{
		if (useHoming)
		{
			useHoming = false;
			Attack attack = attackBox;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			nextTargetInfo = Entity.GetClosestTarget(GameController.enemies, transform.position, 8f, playerTagOnly: false, TargetsHitList, parentObject, requireLOS: true, ChaosCollisions.layerUpperWa
			TargetsHitList.Clear();
			if (nextTargetInfo != null)
			{
				moveVector = (nextTargetInfo.hurtBoxPosition - transform.position).normalized;
				attackBox.knockbackOverwriteVector = moveVector;
				isPointedAtMoveVector = false;
				fullLight = false;
				light.range = 0f;
				light.intensity = 8f;
				startSpeedDecrement = false;
				moveSpeed = 32f;
				RefreshFlightTime();
				return;
			}
		}
		if (!waitingForReset)
		{
			anim.Play("BreakAlt", -1, 0f);
			if ((!hitWall && !disableOnHit) || (disableOnHit && !collided))
			{
				moveSpeed = UnityEngine.Random.Range(5f, 8f);
				rigidbody2D.velocity = moveVector * moveSpeed;
				anim.speed = UnityEngine.Random.Range(0.75f, 1.5f);
			}
			else
			{
				moveSpeed = 0f;
				rigidbody2D.velocity = Vector3.zero;
				ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("WindWallHitEffect");
				int? particleCount = 1;
				Vector3? position = transform.position;
				Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
				poolItem.Emit(particleCount, position, null, localEulerAngles);
				anim.speed = UnityEngine.Random.Range(1.25f, 2f);
			}
			waitingForReset = true;
		}
		else if (!waitingForReset || anim.AnimPlayed())
		{
			base.ResetProjectile();
		}
	}
	private void OnTargetHit(Entity givenEntity)
	{
		if (givenEntity != null)
		{
			TargetsHitList.Add(givenEntity.gameObject);
		}
	}
}
##### BallLightning
public class BallLightning : Projectile
{
	private static GameObject prefab;
	private CircleCollider2D[] circColliders;
	private Color spriteColor;
	private Light spriteLight;
	private ParticleEffect lightningEmitter;
	private ParticleEffect lstEmitter;
	private int baseDamage;
	private bool releaseVarsSet;
	public bool released;
	public int maxCharge = 1;
	public int currentCharge;
	public bool isUltimate;
	public float chargeProgress;
	private float calcKBMultiplier;
	private Entity targetEntity;
	private bool targetHit;
	private int hitStopwatchID;
	private float hitDelay = 0.1f;
	private int secondaryCount = 8;
	private bool isSecondary;
	private int convergeStopwatchID;
	private float convergeDelay = 0.25f;
	private bool secondaryPrimed;
	public Vector3 convergePosition;
	public Vector3 relativeOffset;
	private float LerpValue => (float)currentCharge / (float)maxCharge;
	public override void Awake()
	{
		base.Awake();
		spriteLight = transform.Find("ProjectileLight").GetComponent<Light>();
		spriteColor = projectileSpriteRenderer.color;
		spriteColor.a = 0f;
		projectileSpriteRenderer.color = spriteColor;
		circColliders = GetComponentsInChildren<CircleCollider2D>();
		EnableColliders(status: false);
	}
	public override void Start()
	{
		base.Start();
		baseDamage = Mathf.Max(0, calculatedDamage);
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		if (isUltimate)
		{
			attackBox.knockbackMultiplierOverride = 0f;
		}
		calcKBMultiplier = attackBox.atkInfo.knockbackMultiplier;
		lightningEmitter = PoolManager.GetPoolItem<ParticleEffect>("LightningAuraEffect");
		ParticleEffect particleEffect = lightningEmitter;
		float? emissionRate = 0f;
		Vector3? position = transform.position;
		Transform followTransform = transform;
		ParticleSystemOverride effectBGOverride = LightningAuraEffect.EffectBGOverride;
		particleEffect.Play(emissionRate, position, effectBGOverride, null, followTransform);
	}
	public override void Update()
	{
		if (!isSecondary && !releaseVarsSet)
		{
			chargeProgress = LerpValue;
			HandleChargeProgress(chargeProgress);
			if (!released)
			{
				return;
			}
			releaseVarsSet = true;
			SetReleaseVars();
			moveSpeed *= 0.25f + chargeProgress;
			lightningEmitter.Stop();
			ParticleEffect particleEffect = lightningEmitter;
			float? emissionRate = 10f;
			Vector3? position = transform.position;
			Transform followTransform = transform;
			ParticleSystemOverride effectBGOverride = LightningAuraEffect.EffectBGOverride;
			particleEffect.Play(emissionRate, position, effectBGOverride, null, followTransform);
			lstEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningSectionedTrail");
			lstEmitter.followTransform = transform;
			lstEmitter.reqFollowTrans = true;
			ParticleEffect particleEffect2 = lstEmitter;
			emissionRate = 20f;
			effectBGOverride = new ParticleSystemOverride
			{
				startRotation = Globals.GetRotationVector(moveVector).z + -90f,
				startLifetime = 0.12f
			};
			particleEffect2.Play(emissionRate, null, effectBGOverride);
		}
		if (!targetHit)
		{
			if (isSecondary)
			{
				HandleConverge();
			}
			base.Update();
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Ready:
			currentCharge--;
			if (targetEntity != null && targetEntity.health != null && targetEntity.health.CurrentHealthValue > 0)
			{
				targetEntity.health.TakeDamage(attackBox.atkInfo);
			}
			break;
		case StopwatchState.Done:
			ResetProjectile();
			break;
		}
	}
	private void LateUpdate()
	{
		if (targetEntity != null && targetEntity.hurtBoxTransform != null)
		{
			rigidbody2D.MovePosition(targetEntity.hurtBoxTransform.position);
		}
	}
	public override void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
	{
		if (doCalculations)
		{
			int num = calculatedDamage - otherProjectile.calculatedDamage;
			otherProjectile.calculatedDamage -= calculatedDamage;
			calculatedDamage = num;
			otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
		}
		if (calculatedDamage > 10)
		{
			currentCharge = Mathf.CeilToInt(calculatedDamage / baseDamage);
			otherProjectile.calculatedDamage = 0;
			attackBox.atkInfo.knockbackMultiplier = calcKBMultiplier * LerpValue;
		}
		else
		{
			currentCharge = 0;
			calculatedDamage = 0;
			HandleCollision(other);
		}
		collidedProjectiles.Add(otherProjectile);
	}
	public override void ResetProjectile()
	{
		base.ResetProjectile();
		if (lstEmitter != null)
		{
			lstEmitter.Stop();
		}
		if (lightningEmitter != null)
		{
			lightningEmitter.Stop();
		}
		if (!targetHit)
		{
			string audioID = "BallLightningEnd";
			Vector2? soundOrigin = transform.position;
			float standardPitchRange = SoundManager.StandardPitchRange;
			SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			PoolManager.GetPoolItem<ParticleEffect>("LightningHitEffect").Emit(5, transform.position);
		}
	}
	private void OnTargetHit(Entity hitEntity)
	{
		if (!targetHit && !(hitEntity == null))
		{
			targetHit = true;
			targetEntity = hitEntity;
			updateVelocity = false;
			rigidbody2D.velocity = Vector2.zero;
			if (isUltimate)
			{
				CreateSecondaryBallLightnings(hitEntity.hurtBoxTransform);
			}
			attackBox.atkInfo.knockbackVector = Vector2.zero;
			attackBox.atkInfo.knockbackMultiplier = 0f;
			currentCharge--;
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, currentCharge);
			EnableColliders(status: false);
		}
	}
	private void CreateSecondaryBallLightnings(Transform givenTrans)
	{
		Vector2 vector = ((!(givenTrans == null)) ? givenTrans.position : transform.position);
		convergeStopwatchID = ChaosStopwatch.Begin(convergeDelay);
		for (int i = 0; i < secondaryCount; i++)
		{
			Vector2 circlePositionVector = Globals.GetCirclePositionVector(secondaryCount, i);
			BallLightning component = UnityEngine.Object.Instantiate(prefab, vector + circlePositionVector, Quaternion.identity, transform.parent).GetComponent<BallLightning>();
			component.parentObject = parentObject;
			component.parentEntity = parentEntity;
			component.isSecondary = true;
			component.moveVector = circlePositionVector;
			component.attackBox.SetAttackInfo(attackBox.atkInfo.skillCategory, attackBox.atkInfo.skillID, 3, newIsUltimate: true);
			component.currentCharge = maxCharge;
			component.moveSpeed = 12f;
			component.flyTime = 0.75f;
			component.goThroughWalls = true;
			component.ignoreProjectileCollisions = true;
			component.convergePosition = vector;
			component.convergeStopwatchID = convergeStopwatchID;
			lstEmitter = PoolManager.GetPoolItem<SectionedTrailEmitter>("LightningSectionedTrail");
			lstEmitter.followTransform = component.transform;
			lstEmitter.reqFollowTrans = true;
			ParticleEffect particleEffect = lstEmitter;
			float? emissionRate = 16f;
			ParticleSystemOverride overrides = new ParticleSystemOverride
			{
				startRotation = Globals.GetRotationVector(circlePositionVector).z + -90f,
				startLifetime = 0.12f
