			attackBox.knockbackOverwriteVector = moveVector;
	public override void FixedUpdate()
		if (!boomerangReturning)
			arcLerpValue = arcStopwatch.TimePercentage;
			moveSpeed = Mathf.Lerp(initMoveSpeed, finalMoveSpeed, (!arcSign) ? arcLerpValue : (1f - arcLerpValue));
			if (!ignoreArc)
				calcVector = initMoveVector * moveBias + Vector2.Lerp(leftBound, rightBound, arcLerpValue) * arcBias;
				moveVector = (moveVector + calcVector).normalized;
			if (!arcSign && arcLerpValue >= 1f)
				arcSign = true;
				arcStopwatch.IsRunning = true;
				initMoveVector *= -1f;
				SetBounds(initMoveVector);
				attackBox.ChangeAttackInfoLevel(attackBox.atkInfo.skillLevel + 1);
				goThroughWalls = true;
				ignoreArc = false;
		else if (parentTrans != null)
			calcVector = (parentTrans.position - transform.position).normalized * returnBias;
			prevVector = moveVector;
			moveVector = (moveVector + calcVector).normalized;
			moveSpeed = Mathf.Lerp(initMoveSpeed, finalMoveSpeed, Mathf.Clamp01(Vector2.Angle(prevVector, moveVector) * 0.25f));
