	private void InitArcVars()
		arcStopwatch.SetDelay(flyTime * 0.6f, stopCurrent: false, autoStart: true);
		initMoveSpeed = moveSpeed * 1.5f;
		finalMoveSpeed = moveSpeed;
		initMoveVector = moveVector;
		SetBounds(initMoveVector);
	private void SetBounds(Vector2 givenVector)
		roteAngle = Vector3.Angle(Vector3.up, givenVector) * ((float)Math.PI / 180f) * ((!(givenVector.x > 0f)) ? 1f : (-1f));
		if (positiveArc)
			rightBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
			roteAngle += (float)Math.PI;
			leftBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
		else
			leftBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
			roteAngle += (float)Math.PI;
			rightBound = new Vector2(Mathf.Cos(roteAngle), Mathf.Sin(roteAngle)).normalized;
